export interface ConnectorConfig {
  /** GitHub repository owner (user or organization) */
  githubOwner: string
  /** GitHub repository name */
  githubRepo: string
  /** GitHub personal access token with repo scope (env: GITHUB_TOKEN) */
  githubToken: string
  /** Zendesk API access token (env: ZENDESK_ACCESS_TOKEN) */
  zendeskAccessToken: string
  /** Zendesk subdomain (e.g., 'company' for company.zendesk.com) */
  zendeskSubdomain: string
  /** Optional fetch implementation for testing */
  fetch?: typeof fetch
}

export interface ZendeskTicketPayload {
  ticket: {
    id: number
    subject: string
    description: string
    status: string
    priority: string
    requester_id: number
    submitter_id: number
    assignee_id: number | null
    group_id: number | null
    organization_id: number | null
    tags: string[]
    created_at: string
    updated_at: string
  }
}

export interface HandleResult {
  githubIssueNumber: number
  githubIssueUrl: string
  zendeskTicketId: number
}

async function doFetch(
  fetchFn: typeof fetch,
  url: string,
  options: RequestInit,
): Promise<Response> {
  const response = await fetchFn(url, options)
  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `HTTP ${response.status} ${response.statusText} for ${options.method ?? 'GET'} ${url}: ${text}`,
    )
  }
  return response
}

export async function handle(
  payload: ZendeskTicketPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  // Validate required fields
  if (!payload.ticket) {
    throw new Error('Missing required field: ticket')
  }
  if (typeof payload.ticket.id !== 'number') {
    throw new Error('Missing required field: ticket.id')
  }
  if (!payload.ticket.subject || typeof payload.ticket.subject !== 'string') {
    throw new Error('Missing required field: ticket.subject')
  }
  if (!payload.ticket.description || typeof payload.ticket.description !== 'string') {
    throw new Error('Missing required field: ticket.description')
  }

  const { id: ticketId, subject, description } = payload.ticket

  // Step 1: Create GitHub issue
  const githubUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const githubResponse = await doFetch(fetchFn, githubUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.githubToken}`,
      Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'X-GitHub-Api-Version': '2022-11-28',
    },
    body: JSON.stringify({
      title: subject,
      body: description,
    }),
  })

  const githubIssue = (await githubResponse.json()) as {
    html_url: string
    number: number
  }

  // Step 2: Add comment to Zendesk ticket with GitHub issue URL
  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}`
  const commentBody = `GitHub issue created: ${githubIssue.html_url}`

  await doFetch(fetchFn, zendeskUrl, {
    method: 'PUT',
    headers: {
      Authorization: `Bearer ${config.zendeskAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      ticket: {
        id: ticketId,
        comment: {
          body: commentBody,
          public: true,
        },
      },
    }),
  })

  return {
    githubIssueNumber: githubIssue.number,
    githubIssueUrl: githubIssue.html_url,
    zendeskTicketId: ticketId,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  type RecordedCall,
} from './fixtures'

// Contract test - must be at top level with exact title 'contract'
describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      githubToken: 'gh_test_token',
      zendeskAccessToken: 'zd_test_token',
      zendeskSubdomain: 'company',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.githubIssueNumber).toBe(1347)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/Hello-World/issues/1347')
    expect(result.zendeskTicketId).toBe(12345)
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    githubOwner: 'octocat',
    githubRepo: 'Hello-World',
    githubToken: 'gh_test_token',
    zendeskAccessToken: 'zd_test_token',
    zendeskSubdomain: 'company',
  }

  it('creates GitHub issue and posts comment on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/repos/octocat/Hello-World/issues') && req.method === 'POST') {
        return jsonResponse({
          html_url: 'https://github.com/octocat/Hello-World/issues/42',
          number: 42,
          state: 'open',
          title: 'Test subject',
          body: 'Test description',
        }, 201)
      }
      if (req.url.includes('/api/v2/tickets/12345') && req.method === 'PUT') {
        return jsonResponse({
          ticket: { id: 12345, url: 'https://company.zendesk.com/api/v2/tickets/12345.json', result: 'ok' }
        })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 12345,
        subject: 'Test subject',
        description: 'Test description',
        status: 'open',
        priority: 'normal',
        requester_id: 98765,
        submitter_id: 98765,
        assignee_id: null,
        group_id: null,
        organization_id: null,
        tags: [],
        created_at: '2025-01-15T10:30:00Z',
        updated_at: '2025-01-15T10:30:00Z',
      },
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.githubIssueNumber).toBe(42)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/Hello-World/issues/42')
    expect(result.zendeskTicketId).toBe(12345)

    expect(calls).toHaveLength(2)

    // Verify GitHub issue creation request
    const githubCall = calls[0]
    expect(githubCall.method).toBe('POST')
    expect(githubCall.url).toBe('https://api.github.com/repos/octocat/Hello-World/issues')
    expect(githubCall.json).toEqual({ title: 'Test subject', body: 'Test description' })
    expect(githubCall.headers.get('authorization')).toBe('Bearer gh_test_token')
    expect(githubCall.headers.get('accept')).toBe('application/vnd.github+json')

    // Verify Zendesk comment request
    const zendeskCall = calls[1]
    expect(zendeskCall.method).toBe('PUT')
    expect(zendeskCall.url).toBe('https://company.zendesk.com/api/v2/tickets/12345')
    expect(zendeskCall.json).toEqual({
      ticket: {
        id: 12345,
        comment: { body: 'GitHub issue created: https://github.com/octocat/Hello-World/issues/42', public: true },
      },
    })
    expect(zendeskCall.headers.get('authorization')).toBe('Bearer zd_test_token')
  })

  it('throws descriptive error when ticket is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {} as unknown as ZendeskTicketPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: ticket')
  })

  it('throws descriptive error when ticket.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ticket: { subject: 'x', description: 'y' } } as unknown as ZendeskTicketPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: ticket.id')
  })

  it('throws descriptive error when ticket.subject is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ticket: { id: 1, description: 'y' } } as unknown as ZendeskTicketPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: ticket.subject')
  })

  it('throws descriptive error when ticket.description is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ticket: { id: 1, subject: 'x' } } as unknown as ZendeskTicketPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: ticket.description')
  })

  it('throws error with status and endpoint on GitHub API failure', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ message: 'Validation Failed' }, 422))

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 12345,
        subject: 'Test',
        description: 'Test',
        status: 'open',
        priority: 'normal',
        requester_id: 1,
        submitter_id: 1,
        assignee_id: null,
        group_id: null,
        organization_id: null,
        tags: [],
        created_at: '2025-01-15T10:30:00Z',
        updated_at: '2025-01-15T10:30:00Z',
      },
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'HTTP 422 Unprocessable Entity for POST https://api.github.com/repos/octocat/Hello-World/issues',
    )
  })

  it('throws error with status and endpoint on Zendesk API failure', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/repos/octocat/Hello-World/issues') && req.method === 'POST') {
        return jsonResponse({ html_url: 'https://github.com/octocat/Hello-World/issues/42', number: 42 }, 201)
      }
      return jsonResponse({ error: 'Forbidden' }, 403)
    })

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 12345,
        subject: 'Test',
        description: 'Test',
        status: 'open',
        priority: 'normal',
        requester_id: 1,
        submitter_id: 1,
        assignee_id: null,
        group_id: null,
        organization_id: null,
        tags: [],
        created_at: '2025-01-15T10:30:00Z',
        updated_at: '2025-01-15T10:30:00Z',
      },
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'HTTP 403 Forbidden for PUT https://company.zendesk.com/api/v2/tickets/12345',
    )
  })
})

